SELECT 'notification_owner_disagreement' AS check_name, (SELECT COUNT(*) FROM notifications n LEFT JOIN homework_chat_threads t ON t.id=n.thread_id WHERE (n.student_id IS NOT NULL AND t.student_id IS NOT NULL AND n.student_id<>t.student_id) OR (n.recipient_role='student' AND n.student_id IS NOT NULL AND n.recipient_id<>n.student_id) OR (n.recipient_role='student' AND t.student_id IS NOT NULL AND n.recipient_id<>t.student_id)) AS mismatch_count$$

SELECT 'homework_job_owner_disagreement' AS check_name, (SELECT COUNT(*) FROM homework_file_jobs j JOIN homework_submissions s ON s.id=j.submission_id WHERE j.student_id<>s.student_id OR j.homework_id<>s.homework_id) AS mismatch_count$$

SELECT 'classic_attempt_owner_disagreement' AS check_name, (SELECT COUNT(*) FROM classic_exam_attempts a JOIN classic_exam_assignments g ON g.id=a.assignment_id WHERE a.student_id<>g.student_id OR a.exam_id<>g.exam_id) AS mismatch_count$$

SELECT 'cross_schema_incoming_or_outgoing_fk' AS check_name, (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_SCHEMA IS NOT NULL AND ((TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_SCHEMA<>DATABASE()) OR (REFERENCED_TABLE_SCHEMA=DATABASE() AND TABLE_SCHEMA<>DATABASE()))) AS mismatch_count$$

SELECT 'scheduled_events' AS check_name, (SELECT COUNT(*) FROM information_schema.EVENTS WHERE EVENT_SCHEMA=DATABASE()) AS mismatch_count$$

SELECT 'non_ascii_historical_key:homework_submission_files' AS check_name, (SELECT COUNT(*) FROM `homework_submission_files` WHERE `object_key` IS NOT NULL AND OCTET_LENGTH(`object_key`)<>CHAR_LENGTH(`object_key`)) AS mismatch_count$$

SELECT 'non_ascii_historical_key:homework_file_jobs' AS check_name, (SELECT COUNT(*) FROM `homework_file_jobs` WHERE `staging_key` IS NOT NULL AND OCTET_LENGTH(`staging_key`)<>CHAR_LENGTH(`staging_key`)) AS mismatch_count$$

SELECT 'homework_current_file_id_owner_mismatch' AS check_name, (SELECT COUNT(*) FROM homework_submissions s LEFT JOIN homework_submission_files f ON f.id=s.current_file_id WHERE s.current_file_id IS NOT NULL AND (f.id IS NULL OR f.submission_id<>s.id)) AS mismatch_count$$

SELECT 'homework_draft_file_id_owner_mismatch' AS check_name, (SELECT COUNT(*) FROM homework_submissions s LEFT JOIN homework_submission_files f ON f.id=s.draft_file_id WHERE s.draft_file_id IS NOT NULL AND (f.id IS NULL OR f.submission_id<>s.id)) AS mismatch_count$$

SELECT 'homework_job_result_owner_mismatch' AS check_name, (SELECT COUNT(*) FROM homework_file_jobs j LEFT JOIN homework_submission_files f ON f.id=j.result_file_id WHERE j.result_file_id IS NOT NULL AND (f.id IS NULL OR f.submission_id<>j.submission_id)) AS mismatch_count$$

SELECT 'outbox_unknown_event' AS check_name, (SELECT COUNT(*) FROM homework_realtime_outbox WHERE BINARY event_type NOT IN ('message.created','message.read','typing.changed','submission.changed','job.progress','notification.created')) AS mismatch_count$$

SELECT 'outbox_nonobject_payload' AS check_name, (SELECT COUNT(*) FROM homework_realtime_outbox WHERE payload_json IS NOT NULL AND JSON_TYPE(payload_json)<>'OBJECT') AS mismatch_count$$

SELECT 'outbox_invalid_user_envelope' AS check_name, (SELECT COUNT(*) FROM homework_realtime_outbox WHERE BINARY event_type IN ('submission.changed','job.progress','notification.created') AND NOT COALESCE(thread_id IS NULL AND JSON_TYPE(payload_json)='OBJECT' AND JSON_LENGTH(payload_json)=2 AND JSON_CONTAINS_PATH(payload_json,'all','$.room','$.data') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data'))='OBJECT' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.room'))='STRING' AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.room')),'^user:(student|admin|proctor|examinator|supervisor|staff_admin):[1-9][0-9]*$','c'),FALSE)) AS mismatch_count$$

SELECT 'outbox_notification_entity_orphan' AS check_name, (SELECT COUNT(*) FROM homework_realtime_outbox o LEFT JOIN notifications n ON n.id=o.entity_id WHERE BINARY o.event_type='notification.created' AND n.id IS NULL) AS mismatch_count$$

SELECT 'outbox_message_entity_orphan' AS check_name, (SELECT COUNT(*) FROM homework_realtime_outbox o LEFT JOIN homework_chat_messages m ON m.id=o.entity_id WHERE BINARY o.event_type='message.created' AND o.entity_id IS NOT NULL AND m.id IS NULL) AS mismatch_count$$

SELECT 'outbox_message_thread_mismatch' AS check_name, (SELECT COUNT(*) FROM homework_realtime_outbox o JOIN homework_chat_messages m ON m.id=o.entity_id WHERE BINARY o.event_type IN ('message.created','message.read') AND o.thread_id IS NOT NULL AND o.thread_id<>m.thread_id) AS mismatch_count$$

SELECT 'file_consistency:orphan_file_submission' AS check_name, (SELECT COUNT(*) count FROM homework_submission_files f LEFT JOIN homework_submissions s ON s.id=f.submission_id WHERE (s.id IS NULL)) AS mismatch_count$$

SELECT 'file_consistency:orphan_purge_manifest' AS check_name, (SELECT COUNT(*) count FROM homework_student_purge_objects m LEFT JOIN homework_student_purges p ON CAST(p.job_id AS BINARY)=CAST(m.job_id AS BINARY) WHERE (p.job_id IS NULL)) AS mismatch_count$$

SELECT 'file_consistency:empty_manifest_key' AS check_name, (SELECT COUNT(*) count FROM homework_student_purge_objects m JOIN homework_student_purges p ON CAST(p.job_id AS BINARY)=CAST(m.job_id AS BINARY) WHERE (m.object_key IS NULL OR TRIM(m.object_key)='')) AS mismatch_count$$

SELECT 'file_consistency:orphan_submission_student' AS check_name, (SELECT COUNT(*) count FROM homework_submissions s LEFT JOIN students st ON st.id=s.student_id WHERE (st.id IS NULL)) AS mismatch_count$$

SELECT 'file_consistency:orphan_submission_homework' AS check_name, (SELECT COUNT(*) count FROM homework_submissions s LEFT JOIN homework h ON h.id=s.homework_id WHERE (h.id IS NULL)) AS mismatch_count$$

SELECT 'file_consistency:submission_current_file_id_mismatch' AS check_name, (SELECT COUNT(*) count FROM homework_submissions s LEFT JOIN homework_submission_files f ON f.id=s.current_file_id LEFT JOIN homework_submissions owner ON owner.id=f.submission_id WHERE (s.current_file_id IS NOT NULL AND (f.id IS NULL OR f.submission_id<>s.id OR f.submission_id IS NULL))) AS mismatch_count$$

SELECT 'file_consistency:submission_draft_file_id_mismatch' AS check_name, (SELECT COUNT(*) count FROM homework_submissions s LEFT JOIN homework_submission_files f ON f.id=s.draft_file_id LEFT JOIN homework_submissions owner ON owner.id=f.submission_id WHERE (s.draft_file_id IS NOT NULL AND (f.id IS NULL OR f.submission_id<>s.id OR f.submission_id IS NULL))) AS mismatch_count$$

SELECT 'file_consistency:job_submission_owner_mismatch' AS check_name, (SELECT COUNT(*) count FROM homework_file_jobs j LEFT JOIN homework_submissions s ON s.id=j.submission_id WHERE (s.id IS NULL OR j.student_id IS NULL OR j.homework_id IS NULL OR j.student_id<>s.student_id OR j.homework_id<>s.homework_id)) AS mismatch_count$$

SELECT 'file_consistency:job_result_file_mismatch' AS check_name, (SELECT COUNT(*) count FROM homework_file_jobs j LEFT JOIN homework_submission_files f ON f.id=j.result_file_id LEFT JOIN homework_submissions s ON s.id=j.submission_id LEFT JOIN homework_submissions owner ON owner.id=f.submission_id WHERE (j.result_file_id IS NOT NULL AND (f.id IS NULL OR f.submission_id IS NULL OR f.submission_id<>j.submission_id))) AS mismatch_count$$

SELECT 'file_consistency:ownership_submission_mismatch' AS check_name, (SELECT COUNT(*) count FROM homework_object_ownership o JOIN homework_submissions s ON s.id=o.submission_id WHERE (o.student_id IS NULL OR o.student_id<>s.student_id)) AS mismatch_count$$

SELECT 'file_consistency:ownership_job_mismatch' AS check_name, (SELECT COUNT(*) count FROM homework_object_ownership o JOIN homework_file_jobs j ON CAST(j.id AS BINARY)=CAST(o.upload_job_id AS BINARY) LEFT JOIN homework_submissions s ON s.id=j.submission_id WHERE (o.student_id IS NULL OR o.student_id<>j.student_id OR (o.submission_id IS NOT NULL AND o.submission_id<>j.submission_id))) AS mismatch_count$$

SELECT 'file_consistency:empty_file_key' AS check_name, (SELECT COUNT(*) count FROM homework_submission_files f LEFT JOIN homework_submissions s ON s.id=f.submission_id WHERE (f.object_key IS NULL OR TRIM(f.object_key)='')) AS mismatch_count$$

SELECT 'file_consistency:empty_ownership_key' AS check_name, (SELECT COUNT(*) count FROM homework_object_ownership o WHERE (o.object_key IS NULL OR TRIM(o.object_key)='')) AS mismatch_count$$

SELECT 'file_consistency:empty_job_key' AS check_name, (SELECT COUNT(*) count FROM homework_file_jobs j LEFT JOIN homework_submissions s ON s.id=j.submission_id WHERE ((j.staging_key IS NOT NULL AND TRIM(j.staging_key)='') OR (j.processed_output_key IS NOT NULL AND TRIM(j.processed_output_key)=''))) AS mismatch_count$$

SELECT 'file_consistency:shared_object_ownership' AS check_name, (SELECT COUNT(*) count FROM (SELECT object_key FROM (SELECT CAST(f.object_key AS BINARY) object_key,s.student_id,f.submission_id FROM homework_submission_files f LEFT JOIN homework_submissions s ON s.id=f.submission_id UNION ALL SELECT CAST(staging_key AS BINARY),student_id,submission_id FROM homework_file_jobs WHERE staging_key IS NOT NULL UNION ALL SELECT CAST(processed_output_key AS BINARY),student_id,submission_id FROM homework_file_jobs WHERE processed_output_key IS NOT NULL UNION ALL SELECT CAST(object_key AS BINARY),student_id,submission_id FROM homework_object_ownership UNION ALL SELECT CAST(m.object_key AS BINARY),p.student_id,NULL FROM homework_student_purge_objects m LEFT JOIN homework_student_purges p ON CAST(p.job_id AS BINARY)=CAST(m.job_id AS BINARY)) key_owners WHERE object_key IS NOT NULL GROUP BY object_key HAVING COUNT(DISTINCT student_id)>1) conflicts) AS mismatch_count$$

SELECT 'file_consistency:shared_object_submission' AS check_name, (SELECT COUNT(*) count FROM (SELECT object_key FROM (SELECT CAST(f.object_key AS BINARY) object_key,s.student_id,f.submission_id FROM homework_submission_files f LEFT JOIN homework_submissions s ON s.id=f.submission_id UNION ALL SELECT CAST(staging_key AS BINARY),student_id,submission_id FROM homework_file_jobs WHERE staging_key IS NOT NULL UNION ALL SELECT CAST(processed_output_key AS BINARY),student_id,submission_id FROM homework_file_jobs WHERE processed_output_key IS NOT NULL UNION ALL SELECT CAST(object_key AS BINARY),student_id,submission_id FROM homework_object_ownership UNION ALL SELECT CAST(m.object_key AS BINARY),p.student_id,NULL FROM homework_student_purge_objects m LEFT JOIN homework_student_purges p ON CAST(p.job_id AS BINARY)=CAST(m.job_id AS BINARY)) key_owners WHERE object_key IS NOT NULL GROUP BY object_key HAVING COUNT(DISTINCT submission_id)>1) conflicts) AS mismatch_count$$
DELIMITER ;
